from requests.models import Request

class ProxyIterable:
    def __init__(self, data):
        self._data = data
    def __getattr__(self, name):
        return getattr(self._data, name)
    def __iter__(self):
        return iter(self._data)

def test_proxy_iterable():
    req = Request('POST', 'http://example.com')
    data = ProxyIterable([b'a', b'b'])

    # We want to see if prepare_body treats this as a stream (Iterable)
    # If it does, req._body will be the data object itself (or similar)
    # rather than being processed as a dict/etc.
