import io
from requests.models import Request

class FileWrapper:
    def __init__(self, content):
        self._content = io.BytesIO(content)

    def __getattr__(self, name):
        return getattr(self._content, name)

def test_getattr_file_wrapper():
    content = b"hello world"
    files = {"file": FileWrapper(content)}

    # We want to see if _encode_files correctly identifies FileWrapper as something that can be read.
    # Since _encode_files is a static method of Request, we can call it directly.
    try:
        body, content_type = Request._encode_files(files, None)
        assert content in body
        print("Success: FileWrapper was correctly handled.")
    except Exception as e:
        print(f"Failure: {e}")
        raise e

if __name__ == "__main__":
    test_getattr_file_wrapper()
