from fastapi.testclient import TestClient
from typing import List

app = FastAPI()

@app.post("/test")
async def test_endpoint(form_data: str = Form(...), file: UploadFile = File(...)):
    return {"form_data": form_data, "file": file.filename}

@app.post("/test-multiple")
async def test_multiple(form_data: str = Form(...), files: List[UploadFile] = File(...)):
    return {"form_data": form_data, "files": [f.filename for f in files]}

client = TestClient(app)

def test_form_before_file():
    print("Testing Form before File...")
    response = client.post(
        "/test",
        data={"form_data": "hello"},
        files={"file": ("test.txt", b"content")}
    )
    print(f"Status code: {response.status_code}")
    if response.status_code != 200:
        print(f"Response body: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"form_data": "hello", "file": "test.txt"}

def test_form_before_multiple_files():
    print("Testing Form before Multiple Files...")
    response = client.post(
        "/test-multiple",
        data={"form_data": "hello"},
        files={"files": [("test1.txt", b"content1"), ("test2.txt", b"content2")]}
    )
    print(f"Status code: {response.status_code}")
    if response.status_code != 200:
        print(f"Response body: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"form_data": "hello", "files": ["test1.txt", "test2.txt"]}

if __name__ == "__main__":
    try:
        test_form_before_file()
        test_form_before_multiple_files()
        print("All tests passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        exit(1)
